#!/usr/bin/env python3
import os
import sys
import json
import re
import math
import tempfile

BASE_DIR = "/app/data/cross_sections"
DENSITY_FILE = "/app/data/atomic_densities.txt"
OUTPUT_FILE = "/app/cross_section_report.json"
AVOGADRO = 6.02214076e23

ELEMENT_MAP = {}
_elem_data = [
    ('h', 1, 'hydrogen'), ('he', 2, 'helium'), ('li', 3, 'lithium'),
