]
for sym, z, name in _elem_data:
    ELEMENT_MAP[sym] = z
    ELEMENT_MAP[name] = z
ELEMENT_MAP['aluminium'] = 13
ELEMENT_MAP['sulphur'] = 16
ELEMENT_MAP['caesium'] = 55
ELEMENT_MAP['wolfram'] = 74
ELEMENT_MAP['deuterium'] = 1
ELEMENT_MAP['tritium'] = 1
ELEMENT_MAP['d'] = 1


def find_xs_files():
    xs_files = []
    if not os.path.isdir(BASE_DIR):
        return []
    for root, dirs, files in os.walk(BASE_DIR):
        for f in files:
            if f.endswith(".xs"):
                full = os.path.join(root, f)
                rel = os.path.relpath(full, BASE_DIR)
                depth = rel.count(os.sep)
                xs_files.append((depth, full, rel))
    xs_files.sort(key=lambda x: x[1], reverse=True)
    xs_files.sort(key=lambda x: x[0], reverse=True)
    return xs_files


def normalize_name(name):
    return re.sub(r'[\s\-]', '', name.lower())


def parse_isotope_name(name):
    name = name.strip()
    if not name:
        return None
    cleaned = re.sub(r'[\s\-]', '', name)
    m = re.match(r'^([A-Za-z]+)(\d+)$', cleaned)
    if not m:
        return None
    elem_part = m.group(1)
    mass_str = m.group(2)
    if not elem_part or not mass_str:
        return None
    try:
        mass_num = int(mass_str)
    except ValueError:
        return None
    if mass_num <= 0:
        return None
    z = ELEMENT_MAP.get(elem_part.lower())
    if z is None:
        return None
    return (z, mass_num)


def load_densities():
    densities = []
    if not os.path.isfile(DENSITY_FILE):
        return densities
    with open(DENSITY_FILE, 'r') as f:
        for line in f:
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            parts = stripped.split(':')
            if len(parts) < 3:
                continue
            isotope_name = parts[0]
            try:
                density = float(parts[1])
                atomic_mass = float(parts[2])
            except ValueError:
                continue
            densities.append((isotope_name, density, atomic_mass))
    return densities


def find_density(isotope_name, densities):
    norm_name = normalize_name(isotope_name)
    for name, density, atomic_mass in densities:
        if name == isotope_name:
            return density, atomic_mass
        if name.lower() == isotope_name.lower():
            return density, atomic_mass
        if normalize_name(name) == norm_name:
            return density, atomic_mass
    return None, None


def find_thermal_xs(energy_points, sigma_t_values):
    target = 0.025
    if not energy_points:
        return None, "insufficient_data"
    for i, e in enumerate(energy_points):
        if e == target:
            return sigma_t_values[i], None
    best_idx = None
    best_dist = None
    best_energy = None
    for i, e in enumerate(energy_points):
        dist = abs(e - target)
        if best_idx is None or dist < best_dist or (dist == best_dist and e > best_energy):
            best_dist = dist
            best_idx = i
            best_energy = e
    if best_dist is None or best_dist > 0.1:
        return None, "insufficient_data"
    return sigma_t_values[best_idx], None


def process_file(filepath, relpath, densities, seen_isotopes):
    results = []
    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except Exception:
        return results, False

    lines = content.splitlines()
    isotope_sections = []
    current_name = None
    current_entries = []

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if stripped.startswith('ISOTOPE:'):
            if current_name is not None:
                isotope_sections.append((current_name, current_entries))
            current_name = stripped[len('ISOTOPE:'):].strip()
            current_entries = []
        else:
            if current_name is None:
                continue
            entry = {}
            tokens = stripped.split()
            for token in tokens:
                if ':' in token:
                    key, _, val = token.partition(':')
                    entry[key] = val
            if 'ENERGY' in entry:
                current_entries.append(entry)

    if current_name is not None:
        isotope_sections.append((current_name, current_entries))

    if not isotope_sections:
        return results, False

    for iso_name, entries in isotope_sections:
        iso_result = {
            "isotope": iso_name,
            "source_file": relpath,
            "status": "valid",
            "atomic_density_atoms_cm3": None,
            "macroscopic_cross_section_cm_minus1": None,
            "reaction_rate_reactions_cm3_s": None,
            "thermal_xs_barns": None,
            "validation_errors": []
        }
        errors = set()

        if not iso_name:
            errors.add("invalid_isotope_name")
        else:
            if not parse_isotope_name(iso_name):
                errors.add("invalid_isotope_name")

        if not entries:
            errors.add("invalid_format")

        energy_points = []
        sigma_t_values = []

        if entries:
            for entry in entries:
                if not all(k in entry for k in ['ENERGY', 'SIGMA_T', 'SIGMA_A', 'SIGMA_S']):
                    errors.add("invalid_format")
                    continue
                try:
                    e = float(entry['ENERGY'])
                    st = float(entry['SIGMA_T'])
                    sa = float(entry['SIGMA_A'])
                    ss = float(entry['SIGMA_S'])
                except (ValueError, TypeError):
                    errors.add("invalid_format")
                    continue
                has_bad = False
                for val in [e, st, sa, ss]:
                    if math.isnan(val) or math.isinf(val):
                        has_bad = True
                        break
                if has_bad:
                    errors.add("invalid_format")
                    continue
                if st < 0 or sa < 0 or ss < 0:
                    errors.add("negative_cross_section")
                if abs(st - (sa + ss)) > 0.001:
                    errors.add("cross_section_mismatch")
                energy_points.append(e)
                sigma_t_values.append(st)

            if energy_points and energy_points[0] <= 0:
                errors.add("invalid_energy_ordering")
            if len(energy_points) > 1:
                for i in range(1, len(energy_points)):
                    if energy_points[i] <= energy_points[i-1]:
                        errors.add("invalid_energy_ordering")
                        break

        norm_iso = normalize_name(iso_name) if iso_name else ""
        is_duplicate = False
        if norm_iso and norm_iso in seen_isotopes:
            errors.add("duplicate_isotope")
            is_duplicate = True
        if not is_duplicate and norm_iso:
            seen_isotopes.add(norm_iso)

        iso_result["validation_errors"] = sorted(errors)

        if errors:
            status_priority = [
                "corrupted", "invalid_format", "read_error",
                "cross_section_mismatch", "invalid_energy_ordering",
                "negative_cross_section", "duplicate_isotope",
                "insufficient_data", "missing_density_data",
                "invalid_isotope_name", "valid"
            ]
            for sp in status_priority:
                if sp in errors:
                    iso_result["status"] = sp
                    break
            results.append(iso_result)
            continue

        thermal_xs, thermal_err = find_thermal_xs(energy_points, sigma_t_values)
        if thermal_err:
            iso_result["status"] = thermal_err
            errors.add(thermal_err)
            iso_result["validation_errors"] = sorted(errors)
            results.append(iso_result)
            continue

        iso_result["thermal_xs_barns"] = thermal_xs

        density, atomic_mass = find_density(iso_name, densities)
        if density is None:
            iso_result["status"] = "missing_density_data"
            errors.add("missing_density_data")
            iso_result["validation_errors"] = sorted(errors)
            results.append(iso_result)
            continue

        N_unrounded = (density / atomic_mass) * AVOGADRO
        sigma_cm2 = thermal_xs * 1e-24
        macro_xs_unrounded = N_unrounded * sigma_cm2
        macro_xs_rounded = round(macro_xs_unrounded, 6)
        reaction_rate = 1e14 * macro_xs_rounded
        reaction_rate_rounded = round(reaction_rate, 6)

        iso_result["atomic_density_atoms_cm3"] = round(N_unrounded, 6)
        iso_result["macroscopic_cross_section_cm_minus1"] = macro_xs_rounded
        iso_result["reaction_rate_reactions_cm3_s"] = reaction_rate_rounded
        iso_result["status"] = "valid"
        results.append(iso_result)

    return results, True


def main():
    xs_files = find_xs_files()
    densities = load_densities()
    all_results = []
    seen_isotopes = set()
    total_files = len(xs_files)
    valid_files = 0
    invalid_files = 0

    for depth, filepath, relpath in xs_files:
        file_results, file_valid = process_file(filepath, relpath, densities, seen_isotopes)
        all_results.extend(file_results)
        if file_valid:
            valid_files += 1
        else:
            invalid_files += 1

    def sort_key(item):
        name = item["isotope"]
        parsed = parse_isotope_name(name) if name else None
        if parsed:
            z, a = parsed
            return (-z, -a, [-ord(c) for c in name])
        return (float('inf'), float('inf'), [-ord(c) for c in name])

    all_results.sort(key=sort_key)

    total_isotopes = len(all_results)
    valid_isotopes = sum(1 for r in all_results if r["status"] == "valid")
    invalid_isotopes = total_isotopes - valid_isotopes

    report = {
        "total_files": total_files,
        "valid_files": valid_files,
        "invalid_files": invalid_files,
        "total_isotopes": total_isotopes,
        "valid_isotopes": valid_isotopes,
        "invalid_isotopes": invalid_isotopes,
        "isotopes": all_results
    }

    dir_name = os.path.dirname(os.path.abspath(OUTPUT_FILE))
    fd, tmp_path = tempfile.mkstemp(dir=dir_name, suffix=".tmp")
    try:
        with os.fdopen(fd, 'w') as f:
            json.dump(report, f, indent=2)
        os.rename(tmp_path, OUTPUT_FILE)
    except:
        try:
            os.unlink(tmp_path)
        except:
            pass
        raise


if __name__ == "__main__":
    main()
